-- The sheet's crews: a name (trimmed, unique on the sheet) and a lead, a person of the sheet.
CREATE TABLE crew (
    id        BIGINT        GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id  VARCHAR(200)  NOT NULL REFERENCES sheet (id),
    name      VARCHAR(200)  NOT NULL,
    lead_id   BIGINT        NOT NULL REFERENCES person (id),
    added_by  VARCHAR(200)  NOT NULL,
    CONSTRAINT crew_unique UNIQUE (sheet_id, name)
);
-- A crew's members: people of the sheet, each at most once in a crew and never its lead.
CREATE TABLE crew_member (
    id        BIGINT        GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id  VARCHAR(200)  NOT NULL REFERENCES sheet (id),
    crew_id   BIGINT        NOT NULL REFERENCES crew (id),
    person_id BIGINT        NOT NULL REFERENCES person (id),
    added_by  VARCHAR(200)  NOT NULL,
    CONSTRAINT crew_member_unique UNIQUE (crew_id, person_id)
);
import { getJson, postJson } from '../../api/http';
import { sheetKey } from '../sheet/api';
import { sumDues } from '../rates/api';

/** A member of a crew: a person of the sheet. */
export type CrewMember = { personId: number; name: string };

/** A crew on the sheet: its lead (a person of the sheet) and its members in the order added. */
export type Crew = { id: number; sheetId: string; name: string; leadId: number; lead: string; members: CrewMember[] };

const base = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}/crews`;

export const crewsKey = (sheetId: string) => [...sheetKey(sheetId), 'crews'] as const;

/** The sheet's crews, in the order they were added. */
export function listCrews(sheetId: string): Promise<Crew[]> {
  return getJson<Crew[]>(base(sheetId));
}

/** Add a crew (name trimmed) led by a person; refused (rejects) for a blank name, one already used on the
 *  sheet, or no lead. */
export function addCrew(sheetId: string, by: string, name: string, leadId: number | null): Promise<Crew[]> {
  return postJson<Crew[]>(`${base(sheetId)}?by=${encodeURIComponent(by)}`, { name, leadId });
}

/** Add a person to a crew; refused (rejects) for the crew's lead or a person already in the crew. */
export function addCrewMember(sheetId: string, by: string, crewId: number, personId: number | null): Promise<Crew[]> {
  return postJson<Crew[]>(`${base(sheetId)}/${crewId}/members?by=${encodeURIComponent(by)}`, { personId });
}

/** A crew's due-total: its lead's and its members' due-totals (as their rows show them; null: n/a)
 *  added up, n/a ones skipped. */
export function crewDueTotal(crew: Crew, dueOf: ReadonlyMap<number, string | null>): string {
  return sumDues([crew.leadId, ...crew.members.map((m) => m.personId)].map((id) => dueOf.get(id) ?? null));
}
        jdbc.update("DELETE FROM crew_member WHERE sheet_id = ? AND person_id = ? AND crew_id IN "
                + "(SELECT m.crew_id FROM crew_member m WHERE m.person_id = ?)", sheetId, from.getId(), into.getId());
        jdbc.update("UPDATE crew_member SET person_id = ? WHERE sheet_id = ? AND person_id = ?", into.getId(), sheetId, from.getId());
        jdbc.update("DELETE FROM crew_member WHERE sheet_id = ? AND person_id = ? AND crew_id IN "
                + "(SELECT c.id FROM crew c WHERE c.lead_id = ?)", sheetId, into.getId(), into.getId());
        jdbc.update("DELETE FROM person WHERE sheet_id = ? AND id = ?", sheetId, from.getId());
        withAliases(sheetId, List.of(into));
    }

    /** Move the person to the sheet {@code to} with their grades (and grade history) and aliases, their
     *  statements dropped (the count back to 0) and their plans going with them; their holds, watchers, patron links (either way), pool
     *  and crew memberships (and crews they lead) and closed periods' fixed totals are dropped; they keep the sheet they came from as their
     *  origin. When {@code merging} (they are to be merged into someone there straight after) they keep
     *  their statements and arrive under a stand-in name, as theirs is taken there. Their claims must
     *  have moved first. */
    public void transfer(Person person, String to, boolean merging) {
        String sheetId = person.getSheetId();
        long id = person.getId();
        jdbc.update("DELETE FROM person_patron WHERE sheet_id = ? AND (person_id = ? OR patron_id = ?)", sheetId, id, id);
        for (String table : List.of("person_hold", "person_watch", "pool_member", "crew_member")) {
            jdbc.update("DELETE FROM " + table + " WHERE sheet_id = ? AND person_id = ?", sheetId, id);
        }
        // A crew they lead goes with its memberships.
        jdbc.update("DELETE FROM crew_member WHERE sheet_id = ? AND crew_id IN (SELECT c.id FROM crew c WHERE c.lead_id = ?)",
                sheetId, id);
        jdbc.update("DELETE FROM crew WHERE sheet_id = ? AND lead_id = ?", sheetId, id);
        if (merging) {
            jdbc.update("UPDATE person_statement SET sheet_id = ? WHERE sheet_id = ? AND person_id = ?", to, sheetId, id);
        } else {
            jdbc.update("DELETE FROM person_statement WHERE sheet_id = ? AND person_id = ?", sheetId, id);
            jdbc.update("UPDATE person SET statement_count = 0, stated_total = NULL, statement_date = NULL "
                    + "WHERE sheet_id = ? AND id = ?", sheetId, id);
        }
        jdbc.update("DELETE FROM period_person_total WHERE person_id = ?", id);
        for (String table : List.of("person_grade", "person_terms", "person_grade_history", "person_retired_history", "person_retirement", "person_alias", "plan")) {
            jdbc.update("UPDATE " + table + " SET sheet_id = ? WHERE sheet_id = ? AND person_id = ?", to, sheetId, id);
        }
        String name = merging ? "#merging-" + id : person.getName();
        jdbc.update("UPDATE person SET sheet_id = ?, name = ?, "
                + "origin = ?, list_pos = " + NEXT_POS + " WHERE sheet_id = ? AND id = ?", to, name, sheetId, to, sheetId, id);
    }
